#!/usr/bin/env python3
"""help_check.py - the bundled help topics (design 13 item 12, W4-HELP) and the installer content check (ME-36).

help/*.txt are OUR topic files: line 1 the title, line 2 blank, then the body, ASCII, at most 72 columns (the viewer's
memo does not wrap). The viewer reads them compiled in, from src/windows/lj_help_topics_gen.c (+ .h), which this tool
writes; both installers also ship the .txt files.

  --write                 regenerate src/windows/lj_help_topics_gen.c / .h from help/*.txt
  --check                 (default) topics valid, the generated files current, no FR / DE text, and - where the
                          gitignored reference tree exists (developer PC) - no run of 8+ words shared with Martin's
                          help texts (lj-Help_chm_2.209.txt, the 2.100 and 2.6b6 help). Without it that part is
                          skipped and says so.
  --reference DIR         the reference tree (default: <repo>/reference, else $LJ4EVR_REFERENCE_DIR)
  --install-tree DIR      an installed tree (NSIS install dir, a mounted .dmg or a `cmake --install` prefix): finds
                          THIRD_PARTY_NOTICES.txt beside lj4evr.exe or in LJ4EVR.app/Contents/Resources with the full
                          Apache-2.0 text, the QLC+ NOTICE, the miniz MIT text and the SDL3 zlib text, and every
                          help topic byte-equal to help/; exit 1 on any miss
  --selftest              planted failures (an 8-word run, a German topic, a stale generated file) must be caught
Python 3.12, stdlib only.
"""
import argparse
import os
import re
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.normpath(os.path.join(HERE, ".."))
HELP = os.path.join(ROOT, "help")
GEN_C = os.path.join(ROOT, "src", "windows", "lj_help_topics_gen.c")
GEN_H = os.path.join(ROOT, "src", "windows", "lj_help_topics_gen.h")
REF_TEXTS = ("installer/lj-Help_chm_2.209.txt", "manuals/LJ_2.100_Helpfile.txt", "manuals/lj-Help2_6b6.txt")
RUN = 8           # words: the longest run our text may share with Martin's help
COLS = 72         # the viewer's memo width (lj_help_viewer.c)
# Words that mark French or German prose and never occur in our English topics.
FOREIGN = {"und", "nicht", "werden", "wird", "oder", "auch", "das", "ist", "eine", "einen", "fenster", "datei",
           "avec", "dans", "vous", "les", "une", "sont", "cette", "fichier"}   # not "mit" (MIT licence)
NOTICE_MARKS = ("Apache License", "TERMS AND CONDITIONS", "QLC+", "Rich Geldreich", "Sam Lantinga",
                "Permission is hereby granted")


def words(text):
    return re.findall(r"[a-z0-9]+", text.lower())


def load_topics(folder):
    """{name: (title, [body lines])}; raises ValueError naming the first bad file"""
    out = {}
    for fn in sorted(os.listdir(folder)):
        if not fn.endswith(".txt"):
            continue
        name = fn[:-4]
        raw = open(os.path.join(folder, fn), "rb").read()
        if not re.fullmatch(r"[a-z0-9-]{1,31}", name):
            raise ValueError(f"{fn}: topic names are lower-case a-z 0-9 '-' (at most 31)")
        if any(b > 126 or (b < 32 and b not in (10, 13)) for b in raw):
            raise ValueError(f"{fn}: ASCII only (no tabs, no accents: the topics are English)")
        lines = raw.decode("ascii").replace("\r\n", "\n").split("\n")
        if lines and lines[-1] == "":
            lines.pop()
        if len(lines) < 3 or not lines[0].strip() or lines[1] != "":
            raise ValueError(f"{fn}: line 1 is the title, line 2 is blank")
        for i, l in enumerate(lines, 1):
            if len(l) > COLS:
                raise ValueError(f"{fn}:{i}: {len(l)} columns > {COLS}")
        foreign = sorted(set(words("\n".join(lines))) & FOREIGN)
        if foreign:
            raise ValueError(f"{fn}: French / German words {foreign} (English only, design 13 item 12)")
        out[name] = (lines[0], lines[2:])
    if "index" not in out:
        raise ValueError("help/index.txt missing (the topic NULL opens)")
    return out


def c_str(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def render(topics):
    # index first, then the topics in the order the index lists their titles ("- <Title>: ..."), then any others
    listed = [l[2:].split(":")[0] for l in topics["index"][1] if l.startswith("- ")]
    by_title = {t[0]: n for n, t in topics.items()}
    names = ["index"] + [by_title[t] for t in listed if t in by_title and by_title[t] != "index"]
    names += sorted(n for n in topics if n not in names)
    h = ("/* lj_help_topics_gen.h - GENERATED by tools/help_check.py --write from the help/ topic files; do not edit.\n"
         " * The bundled help topics (design 13 item 12), index first; lj_help_viewer.c shows them. */\n"
         "#ifndef LJ_WINDOWS_HELP_TOPICS_GEN_H\n#define LJ_WINDOWS_HELP_TOPICS_GEN_H\n\n"
         "typedef struct { const char *name, *title; const char *const *lines; int n; } lj_help_topic;\n"
         "extern const lj_help_topic lj_help_topics[];\nextern const int lj_help_ntopics;\n\n"
         "#endif /* LJ_WINDOWS_HELP_TOPICS_GEN_H */\n")
    c = ["/* lj_help_topics_gen.c - GENERATED by tools/help_check.py --write from the help/ topic files; do not edit. */",
         '#include "windows/lj_help_topics_gen.h"', ""]
    for i, n in enumerate(names):
        body = topics[n][1]
        c.append(f"static const char *const lj_ht_{i}[] = {{")
        c += ["    " + c_str(l) + "," for l in body]
        c.append("};")
    c.append("const lj_help_topic lj_help_topics[] = {")
    for i, n in enumerate(names):
        c.append(f"    {{ {c_str(n)}, {c_str(topics[n][0])}, lj_ht_{i}, {len(topics[n][1])} }},")
    c.append("};")
    c.append(f"const int lj_help_ntopics = {len(names)};")
    return "\n".join(c) + "\n", h


def ref_runs(ref_dir):
    """the set of RUN-word tuples of Martin's help texts, or None when the reference tree is absent"""
    if not ref_dir or not os.path.isdir(ref_dir):
        return None
    grams, found = set(), 0
    for rel in REF_TEXTS:
        p = os.path.join(ref_dir, rel)
        if not os.path.isfile(p):
            continue
        found += 1
        w = words(open(p, "rb").read().decode("cp1252", "replace"))
        grams.update(tuple(w[i:i + RUN]) for i in range(len(w) - RUN + 1))
    return grams if found else None


def shared_runs(text, grams):
    w = words(text)
    return [" ".join(w[i:i + RUN]) for i in range(len(w) - RUN + 1) if tuple(w[i:i + RUN]) in grams]


def check(help_dir, gen_c, gen_h, ref_dir, extra_docs=()):
    errs = []
    try:
        topics = load_topics(help_dir)
    except ValueError as e:
        return [str(e)]
    c, h = render(topics)
    for path, want in ((gen_c, c), (gen_h, h)):
        have = open(path, "rb").read().decode("ascii").replace("\r\n", "\n") if os.path.isfile(path) else None
        if have != want:
            errs.append(f"{os.path.basename(path)} is stale: run tools/help_check.py --write")
    grams = ref_runs(ref_dir)
    if grams is None:
        print("help_check: reference help texts absent, the 8-word run check is skipped (developer PC only)")
    else:
        texts = {f"help/{n}.txt": t + "\n" + "\n".join(b) for n, (t, b) in topics.items()}
        for d in extra_docs:
            if os.path.isfile(d):
                texts[os.path.relpath(d, ROOT)] = open(d, "rb").read().decode("utf-8", "replace")
        for name, text in texts.items():
            for run in shared_runs(text, grams)[:3]:
                errs.append(f"{name}: shares {RUN}+ words with Martin's help: '{run}'")
        print(f"help_check: {len(texts)} texts against {len(grams)} reference {RUN}-word runs")
    print(f"help_check: {len(topics)} topics")
    return errs


def install_check(tree):
    errs = []
    cands = [os.path.join(tree, "THIRD_PARTY_NOTICES.txt"),
             os.path.join(tree, "LJ4EVR.app", "Contents", "Resources", "THIRD_PARTY_NOTICES.txt")]
    found = [p for p in cands if os.path.isfile(p)]
    if not found:
        return [f"no THIRD_PARTY_NOTICES.txt in {cands}"]
    for p in found:
        text = open(p, "rb").read().decode("utf-8", "replace")
        errs += [f"{p}: missing '{m}'" for m in NOTICE_MARKS if m not in text]
        hdir = os.path.join(os.path.dirname(p), "help")
        for fn in sorted(os.listdir(HELP)):
            if fn.endswith(".txt"):
                q = os.path.join(hdir, fn)
                if not os.path.isfile(q) or open(q, "rb").read().replace(b"\r\n", b"\n") != open(os.path.join(HELP, fn), "rb").read().replace(b"\r\n", b"\n"):
                    errs.append(f"{q}: missing or differs from help/{fn}")
        print(f"install_check: {p} ok" if not errs else f"install_check: {p}")
    return errs


def selftest():
    bad = 0
    with tempfile.TemporaryDirectory() as t:
        hd, ref = os.path.join(t, "help"), os.path.join(t, "ref", "manuals")
        os.makedirs(hd); os.makedirs(ref)
        open(os.path.join(ref, "LJ_2.100_Helpfile.txt"), "w").write("The quick brown fox jumps over the lazy sleeping dog today.\n")
        open(os.path.join(hd, "index.txt"), "w").write("Index\n\nA fresh sentence of our own.\n")
        gc, gh = os.path.join(t, "g.c"), os.path.join(t, "g.h")
        c, h = render(load_topics(hd))
        open(gc, "w").write(c); open(gh, "w").write(h)
        if check(hd, gc, gh, os.path.join(t, "ref")):
            print("selftest FAIL: a clean tree was rejected"); bad += 1
        open(os.path.join(hd, "copy.txt"), "w").write("Copy\n\nSo the quick brown fox jumps over the lazy sleeping dog.\n")
        c, h = render(load_topics(hd)); open(gc, "w").write(c); open(gh, "w").write(h)
        if not any("shares" in e for e in check(hd, gc, gh, os.path.join(t, "ref"))):
            print("selftest FAIL: an 8-word run was not caught"); bad += 1
        os.remove(os.path.join(hd, "copy.txt"))
        open(os.path.join(hd, "de.txt"), "w").write("Hilfe\n\nDas Fenster wird nicht gezeigt.\n")
        if not any("German" in e for e in check(hd, gc, gh, None)):
            print("selftest FAIL: a German topic was not caught"); bad += 1
        os.remove(os.path.join(hd, "de.txt"))
        open(os.path.join(hd, "new.txt"), "w").write("New\n\nAnother topic.\n")
        if not any("stale" in e for e in check(hd, gc, gh, None)):
            print("selftest FAIL: a stale generated file was not caught"); bad += 1
    print("help_check selftest:", "FAIL" if bad else "OK")
    return 1 if bad else 0


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--write", action="store_true")
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--selftest", action="store_true")
    ap.add_argument("--reference")
    ap.add_argument("--install-tree")
    a = ap.parse_args()
    if a.selftest:
        return selftest()
    if a.install_tree:
        errs = install_check(a.install_tree)
        for e in errs:
            print("FAIL", e)
        return 1 if errs else 0
    if a.write:
        c, h = render(load_topics(HELP))
        for path, text in ((GEN_C, c), (GEN_H, h)):
            with open(path, "w", newline="\n", encoding="ascii") as f:
                f.write(text)
        print("help_check: wrote", os.path.relpath(GEN_C, ROOT), os.path.relpath(GEN_H, ROOT))
        return 0
    ref = a.reference or (os.path.join(ROOT, "reference") if os.path.isdir(os.path.join(ROOT, "reference")) else os.environ.get("LJ4EVR_REFERENCE_DIR"))
    errs = check(HELP, GEN_C, GEN_H, ref, extra_docs=(os.path.join(ROOT, "docs", "user-guide.md"),))
    for e in errs:
        print("FAIL", e)
    return 1 if errs else 0


if __name__ == "__main__":
    sys.exit(main())
